import sys

def to_base36(n, width=4):
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    for _ in range(width):
        result.append(chars[n % 36])
        n //= 36
    return ''.join(reversed(result))

def next_id(id_str):
    suffix = id_str[len("ORD-"):]
    n = int(suffix, 36)
    return "ORD-" + to_base36(n + 1)

